import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  // Load GLB mesh
  let gltfScene = null;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    gltfScene = gltf.scene;
    root.add(gltfScene);
  });

  // Apply cinematic primitives
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (fn) {
        const result = fn(root, prim.params || {});
        if (result?.cleanup) primitiveCleanups.push(result.cleanup);
        if (result?.timeline?.kill) primitiveCleanups.push(() => result.timeline.kill());
      }
    }
  }

  // Interaction timelines storage
  const activeTimelines = [];

  // Hover effect (rise‑in)
  const hoverIn = () => {
    const tl = gsap.to(root.position, {
      y: '+=0.15',
      duration: 0.2,
      ease: 'power2.out',
    });
    activeTimelines.push(tl);
  };
  const hoverOut = () => {
    const tl = gsap.to(root.position, {
      y: '-=0.15',
      duration: 0.2,
      ease: 'power2.in',
    });
    activeTimelines.push(tl);
  };

  // Click effect (emit event)
  const click = () => {
    ctx.emit('hub-home.select', {});
  };

  // Attach handlers
  root.userData.handlers = {
    hover: hoverIn,
    hoverout: hoverOut,
    click,
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    activeTimelines.forEach((t) => t.kill && t.kill());

    // Primitive cleanups
    primitiveCleanups.forEach((fn) => fn && fn());

    // Dispose GLTF resources
    if (gltfScene) {
      gltfScene.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose && m.dispose());
            } else {
              obj.material.dispose && obj.material.dispose();
            }
          }
        }
      });
    }
  };

  return root;
}
